using System;

namespace Eggnog.Relations.Benchmarks
{

    /// <summary>
    /// The workload of the <c>find_only</c> group of egglog's <c>union-find/benches/union-find.rs</c>: seed operations
    /// that build the classes, and identifiers to find. Generated by egglog's <c>find_only_random</c> from a seeded
    /// <see cref="Random"/> (egglog seeds from the OS and regenerates per sample).
    /// </summary>
    internal sealed class FindOnlyWorkload
    {

        /// <summary>
        /// Initializes a new instance.
        /// </summary>
        /// <param name="seedOperations">The operations applied before the measurement.</param>
        /// <param name="toFind">The identifiers the benchmark finds.</param>
        FindOnlyWorkload(UnionFindOperation[] seedOperations, uint[] toFind)
        {
            SeedOperations = seedOperations;
            ToFind = toFind;
        }

        /// <summary>
        /// Gets the operations applied while the input is prepared.
        /// </summary>
        public UnionFindOperation[] SeedOperations { get; }

        /// <summary>
        /// Gets the identifiers the benchmark finds (egglog's <c>to_find</c>).
        /// </summary>
        public uint[] ToFind { get; }

        /// <summary>
        /// egglog's <c>find_only_random</c>: for each identifier <c>i</c> of the first quarter, a union with a uniformly
        /// random identifier <c>r</c> followed by finds of <c>i</c> and <c>r</c>; then <c>2 n</c> random identifiers to
        /// find, shuffled.
        /// </summary>
        /// <param name="itemCount">The number of identifiers.</param>
        /// <param name="randomSeed">The random seed.</param>
        /// <returns>The workload.</returns>
        public static FindOnlyWorkload PrepareRandom(int itemCount, int randomSeed)
        {
            ArgumentOutOfRangeException.ThrowIfLessThan(itemCount, 1);

            var random = new Random(randomSeed);
            var seedOperations = new UnionFindOperation[3 * (itemCount / 4)];
            for (var i = 0; i < itemCount / 4; i++)
            {
                var right = (uint)random.Next(itemCount);
                seedOperations[3 * i] = UnionFindOperation.Union((uint)i, right);
                seedOperations[3 * i + 1] = UnionFindOperation.Find((uint)i);
                seedOperations[3 * i + 2] = UnionFindOperation.Find(right);
            }

            var toFind = new uint[2 * itemCount];
            for (var i = 0; i < toFind.Length; i++)
                toFind[i] = (uint)random.Next(itemCount);

            random.Shuffle(toFind);
            return new FindOnlyWorkload(seedOperations, toFind);
        }

    }

}
